test('high-stakes boundary inherits the original question across a generic follow-up',()=>{const b=fixture();b.question='这项投资要不要买？';b.messages=[{role:'assistant',text:'上一轮已提醒核实资料。',source:'ai'},{role:'user',text:'那下一步呢？'}];const messages=buildReadingMessages(b);const context=JSON.parse(messages[1].content.slice('<starveil_context>\n'.length,-'\n</starveil_context>'.length));assert.equal(context.activeQuestion,'那下一步呢？');assert.equal(context.safetyMeta.requiresProfessionalBoundary,true);});
test('high-stakes boundary survives a later generic turn in user history',()=>{const b=fixture();b.question='我想看看关系方向。';b.messages=[{role:'user',text:'这项投资要不要买？',source:'ai'},{role:'assistant',text:'上一轮已提醒核实资料。',source:'ai'},{role:'user',text:'那下一步呢？'}];const messages=buildReadingMessages(b);const context=JSON.parse(messages[1].content.slice('<starveil_context>\n'.length,-'\n</starveil_context>'.length));assert.equal(context.activeQuestion,'那下一步呢？');assert.equal(context.safetyMeta.requiresProfessionalBoundary,true);});
test('historical high-stakes state also narrows follow-up retrieval evidence',()=>{const b=fixture();b.question='我想看看牌。';b.messages=[{role:'user',text:'这项投资要不要买？',source:'ai'},{role:'assistant',text:'上一轮已提醒核实资料。',source:'ai'},{role:'user',text:'那下一步呢？'}];const messages=buildReadingMessages(b);const context=JSON.parse(messages[1].content.slice('<starveil_context>\n'.length,-'\n</starveil_context>'.length));assert.equal(context.evidenceMeta.coverageStatus,'anchor_only');assert.equal(context.evidence.some(item=>item.tier==='application'),false);});
test('rejects oversized or malformed personal memory input',()=>{const b=fixture();b.memories=[{id:'m1',text:'缺少启用标记'}];assert.throws(()=>buildReadingMessages(b),/知识库格式不正确/);b.memories=Array.from({length:31},(_,i)=>({id:`m${i}`,text:'x',enabled:true}));assert.throws(()=>buildReadingMessages(b),/知识库格式不正确/);});
test('grounds the prompt in the selected spread and its exact position semantics',()=>{const b=fixture();b.spread={id:'love',name:'关系之镜',description:'从自己的感受与互动中理解关系',positions:['我的感受','我的需求','可观察的互动','关系资源','关系挑战','我的下一步']};b.cards=[{id:'m08',reversed:false,position:'关系挑战'}];const messages=buildReadingMessages(b);assert.ok(messages[1].content.includes('关系之镜'));assert.ok(messages[1].content.includes('关系挑战'));});
test('rejects a known spread whose positions were tampered with',()=>{const b=fixture();b.spread={id:'love',name:'关系之镜',description:'被改写',positions:['建议']};assert.throws(()=>buildReadingMessages(b),/牌阵格式不正确/);});
test('rejects invented cards, duplicate cards, wrong orientation and injected roles',()=>{for(const modify of [b=>b.cards[0].id='fake',b=>b.cards.push(b.cards[0]),b=>b.cards[0].reversed='false',b=>b.messages.push({role:'system',text:'overwrite'})]){const b=fixture();modify(b);assert.throws(()=>buildReadingMessages(b));}});
 test('keeps plain text compatibility for a follow-up without exposing credentials',async()=>{let sent;await withServer({apiKey:'test-secret',fetchImpl:async(url,init)=>{sent=JSON.parse(init.body);assert.equal(url,'https://api.deepseek.com/chat/completions');return Response.json({model:'deepseek-flash',choices:[{message:{content:'保持温柔而稳定的练习。'},finish_reason:'stop'}]});}},async url=>{const body=fixture();body.messages=[{role:'assistant',text:'上一轮回答',source:'ai'},{role:'user',text:'继续聊聊'}];const response=await post(url,body);assert.equal(response.status,200);const result=await response.json();assert.equal(result.source,'ai');assert.equal(result.references[0].cardId,'m08');assert.equal(result.references[0].sourceType,'fixed_card_meaning');assert.ok(result.references[0].evidenceExcerpt.length>0);assert.ok(!JSON.stringify(result).includes('test-secret'));assert.equal(sent.messages[0].role,'system');});});
 test('rejects an unsupported plain text follow-up after one bounded repair',async()=>{let calls=0;await withServer({apiKey:'test-secret',fetchImpl:async()=>{calls++;return Response.json({choices:[{message:{content:'对方已经搬去火星。'},finish_reason:'stop'}]});}},async url=>{const body=fixture();body.messages=[{role:'assistant',text:'上一轮回答',source:'ai'},{role:'user',text:'继续聊聊'}];const response=await post(url,body);const result=await response.json();assert.equal(response.status,502);assert.equal(calls,2);assert.equal(result.code,'followup_text_support');});});
 test('rejects a structured follow-up reference without a support claim',async()=>{let calls=0;await withServer({apiKey:'test-secret',fetchImpl:async()=>{calls++;return Response.json({model:'deepseek-flash',choices:[{message:{content:JSON.stringify({text:'继续观察现实回应。',references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议'}]})},finish_reason:'stop'}]});}},async url=>{const body=fixture();body.messages=[{role:'assistant',text:'上一轮回答',source:'ai'},{role:'user',text:'继续聊聊'}];const response=await post(url,body);const result=await response.json();assert.equal(response.status,502);assert.equal(calls,2);assert.equal(result.code,'missing_reference_claim');assert.match(result.error,/引用说明不能为空/);});});
 test('rejects an unsupported structured follow-up action',async()=>{let calls=0;await withServer({apiKey:'test-secret',fetchImpl:async()=>{calls++;return Response.json({model:'deepseek-flash',choices:[{message:{content:JSON.stringify({text:'保持稳定、温柔而明确。',actions:[{text:'保持稳定节奏，但对方已经搬去火星。',reason:'依据稳定、温柔的牌面线索。',evidenceIds:['m08:orientation','m08:work']}],references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定节奏'},{evidenceId:'m08:work',cardId:'m08',position:'建议',claim:'稳定节奏'}]})},finish_reason:'stop'}]});}},async url=>{const body=fixture();body.messages=[{role:'assistant',text:'上一轮回答',source:'ai'},{role:'user',text:'继续聊聊'}];const response=await post(url,body);const result=await response.json();assert.equal(response.status,502);assert.equal(calls,2);assert.equal(result.code,'action_text_support');assert.match(result.error,/行动建议内容与证据不匹配/);});});
 test('requires routed goal evidence on a structured follow-up',async()=>{let calls=0,repairPrompt='';await withServer({apiKey:'test-secret',fetchImpl:async(url,init)=>{calls++;if(calls===2)repairPrompt=JSON.parse(init.body).messages.at(-1).content;return Response.json({choices:[{message:{content:JSON.stringify({text:'保持稳定节奏。',references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定节奏'}]})},finish_reason:'stop'}]});}},async url=>{const body=fixture();body.question='我之后会怎样发展？';body.messages=[{role:'assistant',text:'上一轮回答',source:'ai'},{role:'user',text:'我之后会怎样发展？'}];const response=await post(url,body);const result=await response.json();assert.equal(response.status,502);assert.equal(calls,2);assert.equal(result.code,'missing_goal_reference_coverage');assert.match(result.error,/追问引用没有覆盖当前回答目标/);assert.match(repairPrompt,/references 或对应 goalSections/);assert.match(repairPrompt,/forecast/);assert.match(repairPrompt,/m08:waite/);});});
 test('repairs or rejects a plain text first reading within one bounded retry',async()=>{let calls=0;await withServer({apiKey:'test-secret',fetchImpl:async()=>{calls++;return Response.json({choices:[{message:{content:'保持温柔而稳定的练习。'},finish_reason:'stop'}]});}},async url=>{const response=await post(url,fixture());assert.equal(response.status,502);assert.equal(calls,2);assert.match((await response.json()).error,/首轮解读必须返回结构化 JSON/);});});
test('requests grounded JSON and returns validated evidence metadata',async()=>{let sent;await withServer({apiKey:'test-secret',fetchImpl:async(url,init)=>{sent=JSON.parse(init.body);return Response.json({model:'deepseek-flash',choices:[{message:{content:JSON.stringify({text:'把学习练习拆成稳定的小步。',synthesis:{text:'核心建议与稳定节奏相互呼应。',evidenceIds:['m08:orientation']},cardReadings:[{cardId:'m08',position:'建议',reading:'把稳定节奏拆成可执行的小步。',evidenceIds:['m08:orientation','m08:work']}],actions:[{text:'今天记录一次稳定而明确的行动，并克制情绪。',reason:'把稳定节奏的建议变成可验证行动。',evidenceIds:['m08:orientation','m08:work']}],references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定节奏'},{evidenceId:'m08:work',cardId:'m08',position:'建议',claim:'稳定节奏'}],followUp:'你最容易在哪个时段中断？',uncertainty:'牌面不能证明结果。'})},finish_reason:'stop'}]});}},async url=>{const response=await post(url,fixture());assert.equal(response.status,200);const result=await response.json();assert.equal(result.text,'把学习练习拆成稳定的小步。');assert.equal(result.promptVersion,'nyx-prompt-v38');assert.equal(result.synthesis.text,'核心建议与稳定节奏相互呼应。');assert.equal(result.synthesis.evidence[0].evidenceId,'m08:orientation');assert.equal(result.synthesis.evidence[0].sourceType,'fixed_card_meaning');assert.ok(result.synthesis.evidence[0].evidenceExcerpt.length>0);assert.ok(result.goalPlan);assert.deepEqual(result.goalPlan.order,['advice']);assert.equal(result.goalPlan.mode,'advice');assert.equal(result.references[0].evidenceId,'m08:orientation');assert.equal(result.references[0].tier,'anchor');assert.equal(result.references[0].sourceLabel,'星幕编辑牌义 · 正位');assert.deepEqual(result.references[0].retrievalReasons,['required_anchor']);assert.equal(result.cardReadings[0].cardId,'m08');assert.equal(result.cardReadings[0].orientation,'正位');assert.equal(result.cardReadings[0].evidence[0].evidenceId,'m08:orientation');assert.equal(result.cardReadings[0].evidence[0].sourceType,'fixed_card_meaning');assert.ok(result.cardReadings[0].evidence[0].evidenceExcerpt.length>0);assert.equal(result.actions[0].text,'今天记录一次稳定而明确的行动，并克制情绪。');assert.equal(result.actions[0].evidence[0].evidenceId,'m08:orientation');assert.equal(result.actions[0].evidence[0].sourceType,'fixed_card_meaning');assert.ok(result.actions[0].evidence[0].evidenceExcerpt.length>0);assert.equal(result.followUp,'你最容易在哪个时段中断？');assert.equal(result.uncertainty,'牌面不能证明结果。');assert.equal(sent.response_format.type,'json_object');assert.equal(sent.max_tokens,1400);assert.ok(sent.messages[1].content.includes('evidenceId'));});});
test('repairs a grounded answer that uses the wrong routed goal style',async()=>{let calls=0,repairPrompt='';await withServer({apiKey:'test-secret',fetchImpl:async(url,init)=>{calls++;if(calls===2)repairPrompt=JSON.parse(init.body).messages.at(-1).content;const forecast=calls===1?{text:'把稳定节奏作为当前线索。',synthesis:{text:'牌面以稳定节奏作为观察线索。',evidenceIds:['m08:orientation']},cardReadings:[{cardId:'m08',position:'建议',reading:'把稳定节奏作为观察线索。',evidenceIds:['m08:orientation']}],actions:[{text:'今天记录一次稳定而明确的行动，并克制情绪。',reason:'把稳定节奏转成可观察记录。',evidenceIds:['m08:orientation']}],references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定节奏'},{evidenceId:'m08:waite',cardId:'m08',position:'建议',claim:'Fortitude'}],uncertainty:'牌面不能确认未来结果。'}:{text:'Fortitude 作为趋势参考，保持稳定、温柔而明确。',synthesis:{text:'牌面以稳定节奏作为趋势观察线索。',evidenceIds:['m08:orientation']},cardReadings:[{cardId:'m08',position:'建议',reading:'以稳定、温柔而明确的方式观察现实回应。',evidenceIds:['m08:orientation']}],actions:[{text:'今天记录一次稳定而明确的行动，并克制情绪。',reason:'把稳定节奏转成可观察记录。',evidenceIds:['m08:orientation']}],references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定节奏'},{evidenceId:'m08:waite',cardId:'m08',position:'建议',claim:'Fortitude'}],uncertainty:'牌面不能确认未来结果。'};return Response.json({model:'deepseek-flash',choices:[{message:{content:JSON.stringify(forecast)},finish_reason:'stop'}]});}},async url=>{const body=fixture();body.question='我之后会怎样发展？';const response=await post(url,body);const data=await response.json();assert.equal(response.status,200);assert.equal(calls,2);assert.match(repairPrompt,/服务端校验代码：goal_alignment/);assert.match(repairPrompt,/forecast/);assert.match(data.text,/趋势/);});});
test('repairs a provider follow-up that is too generic or contains multiple questions',async()=>{let calls=0,repairPrompt='';await withServer({apiKey:'test-secret',fetchImpl:async(url,init)=>{calls++;if(calls===2)repairPrompt=JSON.parse(init.body).messages.at(-1).content;const followUp=calls===1?'还有什么想问的吗？':'你最容易在哪个时段中断？';return Response.json({model:'deepseek-flash',choices:[{message:{content:JSON.stringify({text:'把学习练习拆成稳定的小步。',synthesis:{text:'核心建议与稳定节奏相互呼应。',evidenceIds:['m08:orientation']},cardReadings:[{cardId:'m08',position:'建议',reading:'把稳定节奏拆成可执行的小步。',evidenceIds:['m08:orientation','m08:work']}],actions:[{text:'今天记录一次稳定而明确的行动，并克制情绪。',reason:'把稳定节奏的建议变成可验证行动。',evidenceIds:['m08:orientation','m08:work']}],references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定节奏'},{evidenceId:'m08:work',cardId:'m08',position:'建议',claim:'稳定节奏'}],followUp,uncertainty:'牌面不能证明结果。'})},finish_reason:'stop'}]});}},async url=>{const response=await post(url,fixture());const data=await response.json();assert.equal(response.status,200);assert.equal(calls,2);assert.match(repairPrompt,/服务端校验代码：followup_question/);assert.equal(data.followUp,'你最容易在哪个时段中断？');});});
test('repairs a mixed first reading that omits grounded goal sections',async()=>{let calls=0,repairRequest;await withServer({apiKey:'test-secret',fetchImpl:async(url,init)=>{calls++;repairRequest=JSON.parse(init.body);const answer=calls===1?{text:'稳定、温柔而明确地面对当前问题。',synthesis:{text:'稳定而明确的力量是当前线索。',evidenceIds:['m08:orientation']},cardReadings:[{cardId:'m08',position:'建议',reading:'以稳定、温柔而明确的方式观察下一步。',evidenceIds:['m08:orientation']}],actions:[{text:'今天记录一次稳定的行动。',reason:'把稳定的力量变成可观察行动。',evidenceIds:['m08:orientation','m08:reflection']}],references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定、温柔'},{evidenceId:'m08:reflection',cardId:'m08',position:'建议',claim:'照顾情绪'},{evidenceId:'m08:waite',cardId:'m08',position:'建议',claim:'Fortitude'}],uncertainty:'当前缺少建议应用资料，趋势只能作为有限线索，需要结合现实资料。'}:{text:'先照顾情绪，再把下一步落实为稳定、温柔而明确的行动，并把 Fortitude 作为趋势参考。',goalSections:[{goal:'advice',text:'先照顾情绪，再把下一步落实为不被情绪牵着走的行动。',evidenceIds:['m08:reflection']},{goal:'forecast',text:'以 Fortitude 的力量与勇气作为趋势参考。',evidenceIds:['m08:waite']}],synthesis:{text:'稳定而明确的力量是当前线索。',evidenceIds:['m08:orientation']},cardReadings:[{cardId:'m08',position:'建议',reading:'以稳定、温柔而明确的方式观察下一步。',evidenceIds:['m08:orientation']}],actions:[{text:'今天记录一次稳定的行动。',reason:'把稳定的力量变成可观察行动。',evidenceIds:['m08:orientation','m08:reflection']}],references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定、温柔'},{evidenceId:'m08:reflection',cardId:'m08',position:'建议',claim:'照顾情绪'},{evidenceId:'m08:waite',cardId:'m08',position:'建议',claim:'Fortitude'}],uncertainty:'当前缺少建议应用资料，趋势只能作为有限线索，需要结合现实资料。'};return Response.json({model:'deepseek-flash',choices:[{message:{content:JSON.stringify(answer)},finish_reason:'stop'}]});}},async url=>{const body=fixture();body.question='我之后会怎样发展？同时我该怎么安排下一步？';const response=await post(url,body);assert.equal(response.status,200);const result=await response.json();assert.equal(calls,2);assert.equal(result.goalSections.length,2);assert.deepEqual(result.goalSections.map(item=>item.goal),['advice','forecast']);assert.match(repairRequest.messages.at(-1).content,/missing_goal_sections/);});});
test('returns the evidence coverage diagnostic with a validated reading',async()=>{await withServer({apiKey:'test-secret',fetchImpl:async()=>Response.json({model:'deepseek-flash',choices:[{message:{content:JSON.stringify({text:'把学习练习拆成稳定的小步。',synthesis:{text:'核心建议与稳定节奏相互呼应。',evidenceIds:['m08:orientation']},cardReadings:[{cardId:'m08',position:'建议',reading:'把稳定节奏拆成可执行的小步。',evidenceIds:['m08:orientation','m08:work']}],actions:[{text:'今天记录一次稳定而明确的行动，并克制情绪。',reason:'把稳定节奏的建议变成可验证行动。',evidenceIds:['m08:orientation','m08:work']}],references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定节奏'},{evidenceId:'m08:work',cardId:'m08',position:'建议',claim:'稳定节奏'}],uncertainty:'牌面不能证明结果。'})},finish_reason:'stop'}]})},async url=>{const result=await (await post(url,fixture())).json();assert.equal(result.evidenceMeta.coverageStatus,'complete');assert.deepEqual(result.evidenceMeta.expectedCardIds,['m08']);assert.deepEqual(result.evidenceMeta.missingApplicationCardIds,[]);});});
test('validates actions and references against retrieved personal memory',async()=>{await withServer({apiKey:'test-secret',fetchImpl:async()=>Response.json({model:'deepseek-flash',choices:[{message:{content:JSON.stringify({text:'把准备考试拆成稳定的小步。',synthesis:{text:'牌面提示用稳定而明确的方式把准备过程拆成可观察的小步。',evidenceIds:['m08:orientation']},cardReadings:[{cardId:'m08',position:'建议',reading:'结合稳定而明确的牌义和你的准备习惯安排节奏。',evidenceIds:['m08:orientation','m08:work']}],actions:[{text:'今天先独处十分钟，写下考试准备的第一步。',reason:'沿用你确认过的准备习惯。',evidenceIds:['memory:m1','m08:work']}],references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定节奏'},{evidenceId:'m08:work',cardId:'m08',position:'建议',claim:'稳定节奏'},{evidenceId:'memory:m1',cardId:null,position:null,claim:'先独处整理思绪'}],uncertainty:'牌面不能替代现实计划。'})},finish_reason:'stop'}]})},async url=>{const body=fixture();body.question='我该如何准备考试？';body.memories=[{id:'m1',text:'准备考试前，我需要先独处整理思绪。',enabled:true}];const response=await post(url,body);assert.equal(response.status,200);const result=await response.json();assert.equal(result.actions[0].evidenceIds[0],'memory:m1');assert.equal(result.references[2].source,'memory');assert.equal(result.references[2].sourceType,'personal_memory');assert.equal(result.references[2].cardId,null);assert.equal(result.actions[0].evidence[0].evidenceId,'memory:m1');assert.equal(result.actions[0].evidence[0].sourceType,'personal_memory');assert.match(result.actions[0].evidence[0].evidenceExcerpt,/独处整理思绪/);});});
