test('repair prompt explains synthesis grounding failures',async()=>{
 let calls=0,repairPrompt='';
 await withServer({apiKey:'test-secret',fetchImpl:async(url,init)=>{
  calls++;
  const sent=JSON.parse(init.body);
  if(calls===2)repairPrompt=sent.messages.at(-1).content;
  const content=calls===1?JSON.stringify({
   text:'把学习练习拆成稳定的小步。',
   synthesis:{text:'这意味着对方一定会回来。',evidenceIds:['m08:orientation']},
   cardReadings:[{cardId:'m08',position:'建议',reading:'用稳定而明确的方式观察一个可验证的角度。',evidenceIds:['m08:orientation','m08:work']}],
   actions:[{text:'今天记录一次稳定节奏的具体行动。',reason:'把牌面的稳定线索转成可核验步骤。',evidenceIds:['m08:orientation','m08:work']}],
   references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定节奏'},{evidenceId:'m08:work',cardId:'m08',position:'建议',claim:'稳定节奏'}],
   uncertainty:'牌面不能证明结果。'
  }):JSON.stringify({
   text:'把学习练习拆成稳定的小步。',
   synthesis:{text:'牌面提示稳定节奏。',evidenceIds:['m08:orientation']},
   cardReadings:[{cardId:'m08',position:'建议',reading:'结合稳定而明确的核心锚点观察一个角度。',evidenceIds:['m08:orientation','m08:work']}],
   actions:[{text:'今天记录一次稳定节奏的行动。',reason:'把牌面的稳定线索转成可核验步骤。',evidenceIds:['m08:orientation','m08:work']}],
   references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定节奏'},{evidenceId:'m08:work',cardId:'m08',position:'建议',claim:'稳定节奏'}],
   uncertainty:'牌面不能证明结果。'
  });
  return Response.json({choices:[{message:{content},finish_reason:'stop'}]});
 }},async url=>{
  const response=await post(url,fixture());
  assert.equal(response.status,200);
  assert.equal(calls,2);
  assert.match(repairPrompt,/服务端校验代码：synthesis_support/);
  assert.match(repairPrompt,/synthesis.text 必须复述所引 evidence 中的具体、非通用概念/);
 });
});
test('rejects an unsupported first synthesis after one bounded repair',async()=>{let calls=0;await withServer({apiKey:'test-secret',fetchImpl:async()=>{calls++;return Response.json({choices:[{message:{content:JSON.stringify({text:'把学习练习拆成稳定的小步。',synthesis:{text:'这意味着对方一定会回来。',evidenceIds:['m08:orientation']},cardReadings:[{cardId:'m08',position:'建议',reading:'用稳定而明确的方式观察一个可验证的角度。',evidenceIds:['m08:orientation']}],actions:[{text:'今天记录一次稳定节奏的具体行动。',reason:'把牌面的观察落到现实记录。',evidenceIds:['m08:orientation','m08:work']}],references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定节奏'},{evidenceId:'m08:work',cardId:'m08',position:'建议',claim:'稳定节奏'}],uncertainty:'牌面不能证明结果。'})}}]})}},async url=>{const response=await post(url,fixture());const data=await response.json();assert.equal(response.status,502);assert.equal(calls,2);assert.equal(data.code,'synthesis_support');});});

