test('rejects a multi-card synthesis that only supports one card',async()=>{
 let calls=0;
 await withServer({apiKey:'test-secret',fetchImpl:async()=>{
  calls++;
  const content=JSON.stringify({
   text:'先把稳定表达和当前事实分开观察。',
   synthesis:{text:'只复述第一张牌的稳定与温柔。',evidenceIds:['m08:orientation','c06:orientation']},
   cardReadings:[
   {cardId:'m08',position:'建议',reading:'结合稳定而明确的方式，先克制情绪。',evidenceIds:['m08:orientation']},
   {cardId:'c06',position:'关系挑战',reading:'比较记忆和当前事实，再不因熟悉就忽略变化。',evidenceIds:['c06:orientation']},
  ],
  actions:[{text:'今天记录一次稳定行动，并克制情绪。',reason:'依据稳定和克制的行动提示。',evidenceIds:['m08:orientation']}],
   references:[
    {evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定、明确'},
    {evidenceId:'c06:orientation',cardId:'c06',position:'关系挑战',claim:'当前事实'},
   ],
   uncertainty:'牌面不能确认对方的真实想法。',
  });
  return Response.json({choices:[{message:{content},finish_reason:'stop'}]});
 }},async url=>{
  const body=fixture();
  body.question='我该怎样处理这段关系？';
  body.cards=[{id:'m08',reversed:false,position:'建议'},{id:'c06',reversed:true,position:'关系挑战'}];
  const response=await post(url,body);
  const data=await response.json();
  assert.equal(response.status,502);
  assert.equal(calls,2);
  assert.equal(data.code,'synthesis_support');
 });
});
test('requires an application evidence citation for an advice goal',async()=>{let calls=0,repairPrompt='';await withServer({apiKey:'test-secret',fetchImpl:async(url,init)=>{calls++;if(calls===2)repairPrompt=JSON.parse(init.body).messages.at(-1).content;return Response.json({model:'deepseek-flash',choices:[{message:{content:JSON.stringify({text:'把学习练习拆成稳定的小步。',synthesis:{text:'核心建议与稳定节奏相互呼应。',evidenceIds:['m08:orientation']},cardReadings:[{cardId:'m08',position:'建议',reading:'把稳定节奏拆成可执行的小步。',evidenceIds:['m08:orientation','m08:work']}],actions:[{text:'今天记录一次稳定而明确的行动，并克制情绪。',reason:'把稳定节奏的建议变成可验证行动。',evidenceIds:['m08:orientation','m08:work']}],references:[{evidenceId:'m08:orientation',cardId:'m08',position:'建议',claim:'稳定节奏'}],uncertainty:'牌面不能证明结果。'})},finish_reason:'stop'}]});}},async url=>{const response=await post(url,fixture());const data=await response.json();assert.equal(response.status,502);assert.equal(calls,2);assert.equal(data.code,'missing_goal_reference_coverage');assert.match(repairPrompt,/advice/);assert.match(repairPrompt,/application/);assert.match(repairPrompt,/m08:work/);});});

